import 'dart:async';

import 'package:cloud_firestore/cloud_firestore.dart' hide Order;

import '../../domain/entities/cart_item.dart';
import '../../domain/entities/order.dart';
import '../../domain/entities/product.dart';
import '../../domain/repositories/order_repository.dart';
import '../mappers/order_mapper.dart';

/// Firestore-backed [OrderRepository]. Order ids are human-readable (TT####)
/// generated by a transactional counter so numbering is consistent.
class FirestoreOrderRepository implements OrderRepository {
  final FirebaseFirestore _firestore;

  FirestoreOrderRepository(this._firestore);

  CollectionReference<Map<String, dynamic>> get _col =>
      _firestore.collection('orders');

  DocumentReference<Map<String, dynamic>> get _counter =>
      _firestore.doc('counters/orders');

  Future<String> _nextOrderId() {
    return _firestore.runTransaction((tx) async {
      final snap = await tx.get(_counter);
      final current = ((snap.data()?['value'] ?? 1042) as num).toInt();
      final next = current + 1;
      tx.set(_counter, {'value': next}, SetOptions(merge: true));
      return 'TT$next';
    });
  }

  @override
  Future<Order> placeOrder({
    required List<CartItem> items,
    required DeliveryMethod deliveryMethod,
    required PaymentMethod paymentMethod,
    required String customerName,
    String? customerId,
    String? customerPhone,
    String? customerAddress,
  }) async {
    final id = await _nextOrderId();
    final order = Order(
      id: id,
      customerId: customerId,
      customerName: customerName.isNotEmpty ? customerName : 'Customer',
      customerPhone: customerPhone,
      customerAddress: customerAddress,
      items: items,
      originalItems: items,
      deliveryMethod: deliveryMethod,
      paymentMethod: paymentMethod,
      status: OrderStatus.placed,
      placedAt: DateTime.now(),
    );
    await _col.doc(id).set(OrderMapper.toMap(order));
    return order;
  }

  @override
  Stream<List<Order>> watchOrders() {
    return _col
        .orderBy('placedAt', descending: true)
        .snapshots()
        .map(
          (snapshot) => snapshot.docs
              .map((doc) => OrderMapper.fromMap(doc.id, doc.data()))
              .toList(),
        );
  }

  @override
  Stream<List<Order>> watchCustomerOrders({
    required String customerId,
    String? customerPhone,
  }) {
    final byId = _col
        .where('customerId', isEqualTo: customerId)
        .snapshots()
        .map(
          (snapshot) => snapshot.docs
              .map((doc) => OrderMapper.fromMap(doc.id, doc.data()))
              .toList(),
        );

    if (customerPhone == null || customerPhone.isEmpty) {
      return byId.map(
        (orders) => orders..sort((a, b) => b.placedAt.compareTo(a.placedAt)),
      );
    }

    // Fallback for orders placed before user scoping was added: include orders
    // that have the same phone number but no customerId. Sorted in memory so
    // no composite Firestore index is required.
    final byPhone = _col
        .where('customerPhone', isEqualTo: customerPhone)
        .snapshots()
        .map(
          (snapshot) => snapshot.docs
              .map((doc) => OrderMapper.fromMap(doc.id, doc.data()))
              .where(
                (o) =>
                    o.customerId == null ||
                    o.customerId!.isEmpty ||
                    o.customerId == customerId,
              )
              .toList(),
        );

    return _mergeOrderStreams([byId, byPhone]);
  }

  static Stream<List<Order>> _mergeOrderStreams(
    List<Stream<List<Order>>> streams,
  ) {
    final latest = List<List<Order>>.generate(streams.length, (_) => const []);
    StreamController<List<Order>>? controller;
    final subscriptions = <StreamSubscription<List<Order>>>[];

    controller = StreamController<List<Order>>(
      onListen: () {
        for (var i = 0; i < streams.length; i++) {
          final index = i;
          subscriptions.add(
            streams[index].listen((data) {
              latest[index] = data;
              final seen = <String>{};
              final combined =
                  latest.expand((l) => l).where((o) => seen.add(o.id)).toList()
                    ..sort((a, b) => b.placedAt.compareTo(a.placedAt));
              controller?.add(combined);
            }, onError: (Object e) => controller?.addError(e)),
          );
        }
      },
      onCancel: () {
        for (final sub in subscriptions) {
          sub.cancel();
        }
        subscriptions.clear();
      },
    );

    return controller.stream;
  }

  @override
  Future<void> updateStatus({
    required String orderId,
    required OrderStatus status,
  }) => _col.doc(orderId).update({'status': status.name});

  @override
  Future<void> reviseAndApprove({
    required String orderId,
    required List<CartItem> items,
    required bool modified,
  }) {
    final total = items.fold<int>(
      0,
      (runningTotal, item) => runningTotal + item.lineTotal,
    );
    return _col.doc(orderId).update({
      'items': items.map(CartItemMapper.toMap).toList(),
      'status': OrderStatus.approved.name,
      'modifiedByAdmin': modified,
      'totalAmount': total,
    });
  }

  @override
  Future<void> markPaid({
    required String orderId,
    PaymentMethod? paymentMethod,
  }) async {
    final update = <String, dynamic>{'isPaid': true};
    if (paymentMethod != null) {
      update['paymentMethod'] = paymentMethod.name;
    }
    await _col.doc(orderId).update(update);
  }

  @override
  Future<Order> placeListOrder({
    required List<String> imageUrls,
    required String customerName,
    String? customerId,
    String? customerPhone,
    String? customerAddress,
  }) async {
    final id = await _nextOrderId();
    final order = Order(
      id: id,
      customerId: customerId,
      customerName: customerName.isNotEmpty ? customerName : 'Customer',
      customerPhone: customerPhone,
      customerAddress: customerAddress,
      items: const [],
      originalItems: const [],
      deliveryMethod: DeliveryMethod.homeDelivery,
      paymentMethod: PaymentMethod.cash,
      status: OrderStatus.placed,
      placedAt: DateTime.now(),
      orderListImageUrls: imageUrls,
    );
    await _col.doc(id).set(OrderMapper.toMap(order));
    return order;
  }

  @override
  Future<void> uploadHandwrittenBillImage({
    required String orderId,
    required String imageUrl,
  }) => _col.doc(orderId).update({
    'handwrittenBillImageUrls': FieldValue.arrayUnion([imageUrl]),
  });

  @override
  Future<void> setFinalBillAmount({
    required String orderId,
    required int amount,
  }) async {
    final billProduct = Product(
      id: '__final_bill__',
      name: 'Final bill',
      unit: 'as per list',
      category: 'Other',
      price: amount,
      emoji: '🧾',
    );
    final item = CartItem(product: billProduct, quantity: 1);
    await _col.doc(orderId).update({
      'items': [CartItemMapper.toMap(item)],
      'originalItems': [CartItemMapper.toMap(item)],
      'totalAmount': amount,
    });
  }
}
